import React, { useState, useEffect } from 'react';
import './App.css';
import { WiThermometer, WiHumidity, WiStrongWind, WiRain, WiBarometer, WiSunrise, WiSunset } from 'react-icons/wi';
import { FaCloudSunRain, FaTemperatureHigh } from 'react-icons/fa';

export default function Weather() {
  const [weatherData, setWeatherData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [forecast, setForecast] = useState([]);
  const [time, setTime] = useState(new Date());

  // Update time every minute
  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date());
    }, 60000);
    
    return () => clearInterval(timer);
  }, []);

  // Mock API data - no actual API key needed
  useEffect(() => {
    const fetchWeatherData = () => {
      // Simulate API loading delay
      setTimeout(() => {
        // Mock data for Oujda, Morocco
        const mockWeatherData = {
          city: "Oujda",
          country: "Morocco",
          temperature: 24,
          feels_like: 25,
          humidity: 65,
          wind_speed: 12,
          wind_direction: 180,
          description: "Partly cloudy with light rain",
          weather_icon: "cloud-sun-rain",
          pressure: 1013,
          visibility: 10,
          sunrise: "06:45",
          sunset: "20:30",
          rain_chance: 40,
          rain_amount: 0.5,
          uv_index: 6,
          last_updated: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          hourly: [
            { time: "Now", temp: 24, icon: "cloud-sun-rain", rain: 40 },
            { time: "1 PM", temp: 25, icon: "cloud-sun", rain: 20 },
            { time: "2 PM", temp: 26, icon: "cloud-sun", rain: 10 },
            { time: "3 PM", temp: 27, icon: "sun", rain: 0 },
            { time: "4 PM", temp: 26, icon: "sun", rain: 0 },
            { time: "5 PM", temp: 25, icon: "cloud-sun", rain: 10 },
            { time: "6 PM", temp: 23, icon: "cloud", rain: 30 },
          ]
        };

        // Mock 5-day forecast
        const mockForecast = [
          { day: "Today", high: 27, low: 18, icon: "cloud-sun-rain", rain: 40 },
          { day: "Tomorrow", high: 28, low: 19, icon: "sun", rain: 10 },
          { day: "Wed", high: 26, low: 17, icon: "cloud-sun", rain: 20 },
          { day: "Thu", high: 25, low: 16, icon: "cloud", rain: 60 },
          { day: "Fri", high: 27, low: 18, icon: "sun", rain: 0 },
        ];

        setWeatherData(mockWeatherData);
        setForecast(mockForecast);
        setLoading(false);
      }, 800); // Simulate network delay
    };

    fetchWeatherData();
  }, []);

  // Get weather icon component
  const getWeatherIcon = (iconName) => {
    switch (iconName) {
      case 'sun':
        return <WiThermometer className="weather-icon" />;
      case 'cloud-sun':
        return <FaCloudSunRain className="weather-icon" />;
      case 'cloud':
        return <WiRain className="weather-icon" />;
      case 'cloud-sun-rain':
        return <FaCloudSunRain className="weather-icon" />;
      default:
        return <WiThermometer className="weather-icon" />;
    }
  };

  // Get wind direction from degrees
  const getWindDirection = (degrees) => {
    if (degrees >= 337.5 || degrees < 22.5) return "N";
    if (degrees >= 22.5 && degrees < 67.5) return "NE";
    if (degrees >= 67.5 && degrees < 112.5) return "E";
    if (degrees >= 112.5 && degrees < 157.5) return "SE";
    if (degrees >= 157.5 && degrees < 202.5) return "S";
    if (degrees >= 202.5 && degrees < 247.5) return "SW";
    if (degrees >= 247.5 && degrees < 292.5) return "W";
    return "NW";
  };

  // Determine rain status
  const getRainStatus = () => {
    if (!weatherData) return { text: "Loading...", color: "gray" };
    if (weatherData.rain_chance >= 60) return { text: "High chance of rain", color: "#9c27b0" };
    if (weatherData.rain_chance >= 30) return { text: "Possible rain", color: "#7b1fa2" };
    return { text: "Unlikely to rain", color: "#4a148c" };
  };

  // Format date
  const formatDate = (date) => {
    const options = { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' };
    return date.toLocaleDateString('en-US', options);
  };

  if (loading) {
    return (
      <div className="app">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <h2>Loading Oujda Weather...</h2>
          <p>Fetching weather data</p>
        </div>
      </div>
    );
  }

  const rainStatus = getRainStatus();

  return (
    <div className="app">
      <header className="header">
        <div className="header-content">
          <h1><span className="purple-text">Oujda</span> Weather</h1>
          <p className="subtitle">实时天气 • طقس وجدة • {formatDate(time)}</p>
          <div className="current-time">
            <span className="time">{time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            <span className="time-label">Local Time</span>
          </div>
        </div>
      </header>

      <main className="main-content">
        {/* Current Weather Card */}
        <div className="weather-card main-weather">
          <div className="location-info">
            <h2>{weatherData.city}, {weatherData.country}</h2>
            <p className="weather-description">{weatherData.description}</p>
            <p className="last-updated">Last updated: {weatherData.last_updated}</p>
          </div>

          <div className="weather-main">
            <div className="temperature-section">
              <div className="current-temp">
                <span className="temp-value">{weatherData.temperature}</span>
                <span className="temp-unit">°C</span>
              </div>
              <div className="feels-like">
                <FaTemperatureHigh className="icon" />
                <span>Feels like {weatherData.feels_like}°C</span>
              </div>
            </div>

            <div className="weather-icon-large">
              {getWeatherIcon(weatherData.weather_icon)}
            </div>

            <div className="weather-details">
              <div className="detail-item">
                <WiHumidity className="detail-icon" />
                <div className="detail-text">
                  <span className="detail-value">{weatherData.humidity}%</span>
                  <span className="detail-label">Humidity</span>
                </div>
              </div>

              <div className="detail-item">
                <WiStrongWind className="detail-icon" />
                <div className="detail-text">
                  <span className="detail-value">{weatherData.wind_speed} km/h</span>
                  <span className="detail-label">Wind • {getWindDirection(weatherData.wind_direction)}</span>
                </div>
              </div>

              <div className="detail-item">
                <WiBarometer className="detail-icon" />
                <div className="detail-text">
                  <span className="detail-value">{weatherData.pressure} hPa</span>
                  <span className="detail-label">Pressure</span>
                </div>
              </div>
            </div>
          </div>

          {/* Rain Probability */}
          <div className="rain-section" style={{ backgroundColor: rainStatus.color + '20' }}>
            <div className="rain-header">
              <WiRain className="rain-icon" />
              <h3>Rain Probability</h3>
            </div>
            <div className="rain-content">
              <div className="rain-chance">
                <span className="rain-percentage">{weatherData.rain_chance}%</span>
                <span className="rain-text">{rainStatus.text}</span>
              </div>
              <div className="rain-details">
                <p>Expected rainfall: <strong>{weatherData.rain_amount} mm</strong></p>
                <div className="rain-bar">
                  <div 
                    className="rain-fill" 
                    style={{ 
                      width: `${weatherData.rain_chance}%`,
                      backgroundColor: rainStatus.color
                    }}
                  ></div>
                </div>
              </div>
            </div>
          </div>

          {/* Sunrise/Sunset */}
          <div className="sun-times">
            <div className="sun-item">
              <WiSunrise className="sun-icon sunrise" />
              <div className="sun-info">
                <span className="sun-label">Sunrise</span>
                <span className="sun-time">{weatherData.sunrise} AM</span>
              </div>
            </div>
            <div className="sun-item">
              <WiSunset className="sun-icon sunset" />
              <div className="sun-info">
                <span className="sun-label">Sunset</span>
                <span className="sun-time">{weatherData.sunset} PM</span>
              </div>
            </div>
          </div>
        </div>

        {/* Today's Forecast */}
        <div className="forecast-card">
          <h3>Today's Forecast</h3>
          <div className="hourly-forecast">
            {weatherData.hourly.map((hour, index) => (
              <div className="hour-item" key={index}>
                <span className="hour-time">{hour.time}</span>
                <div className="hour-icon">{getWeatherIcon(hour.icon)}</div>
                <span className="hour-temp">{hour.temp}°</span>
                <div className="hour-rain">
                  <span className="rain-percent">{hour.rain}%</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* 5-Day Forecast */}
        <div className="forecast-card weekly">
          <h3>5-Day Forecast</h3>
          <div className="weekly-forecast">
            {forecast.map((day, index) => (
              <div className="day-item" key={index}>
                <span className="day-name">{day.day}</span>
                <div className="day-icon">{getWeatherIcon(day.icon)}</div>
                <div className="day-temps">
                  <span className="day-high">{day.high}°</span>
                  <span className="day-low">{day.low}°</span>
                </div>
                <div className="day-rain">
                  <WiRain className="rain-icon-small" />
                  <span>{day.rain}%</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Weather Tips */}
        <div className="tips-card">
          <h3>Weather Tips for Oujda</h3>
          <div className="tips-content">
            <div className="tip">
              <div className="tip-icon">🌡️</div>
              <div className="tip-text">
                <h4>Temperature</h4>
                <p>Average temperatures range from 8°C in winter to 35°C in summer.</p>
              </div>
            </div>
            <div className="tip">
              <div className="tip-icon">💧</div>
              <div className="tip-text">
                <h4>Rainfall</h4>
                <p>Most rain falls between November and March. Summer months are generally dry.</p>
              </div>
            </div>
            <div className="tip">
              <div className="tip-icon">🌬️</div>
              <div className="tip-text">
                <h4>Wind</h4>
                <p>Oujda experiences moderate winds throughout the year, stronger in spring.</p>
              </div>
            </div>
          </div>
        </div>
      </main>

      <footer className="footer">
        <div className="footer-content">
          <p>🌤️ Weather App for Oujda, Morocco • No API Key Required • Purple Theme Design</p>
          <p className="footer-note">This app uses mock weather data. For real-time data, connect to OpenWeatherMap API.</p>
          <div className="footer-links">
            <span>Oujda Coordinates: 34.6810° N, 1.9086° W</span>
            <span>•</span>
            <span>Elevation: 470m</span>
            <span>•</span>
            <span>Population: 494,252</span>
          </div>
        </div>
      </footer>
    </div>
  );
}
